  "Proceed": "继续",
  "Which kind of wallet were these words used in?": "这些单词曾用于哪种钱包？",
  "Block key uses": "区块密钥计数",
  "A wallet made in Pandamonium on a phone, or made new in this app.": "在手机上的 Pandamonium 中创建的钱包，或在本应用中新建的钱包。",
  "Classic": "经典",
  "A wallet made in an older Minima Core, in MinimaClassic, or with Classic mode switched on.": "在旧版 Minima Core、MinimaClassic 中创建的钱包，或在开启经典模式时创建的钱包。",
  "The same 24 words give different addresses in each mode. Choose with care: the choice is recorded for this install and cannot be changed afterwards. If you choose the wrong one, the wallet opens with no funds in it. Nothing is lost, but the other mode then needs a fresh install of the app, where you choose again.": "同样的 24 个单词在两种模式下会得到不同的地址。请谨慎选择：此选择会记录在本次安装中，之后无法更改。如果选错，打开的钱包里不会有资金。资金不会丢失，但要使用另一种模式，就必须全新安装本应用并重新选择。",
  "Was this backup made by a wallet using block key uses, such as Pandamonium on a phone with default settings, or classic keys?": "此备份是由使用区块密钥计数的钱包（例如手机上默认设置的 Pandamonium）创建的，还是由使用经典密钥的钱包创建的？",
  "Pandamonium on a phone with default settings, or a wallet made new in an app that uses block key uses.": "手机上默认设置的 Pandamonium，或在使用区块密钥计数的应用中新建的钱包。",
  "Classic keys": "经典密钥",
  "An older Minima Core, MinimaClassic, or a wallet made with Classic mode switched on.": "旧版 Minima Core、MinimaClassic，或在开启经典模式时创建的钱包。",
  "Choose which kind of wallet these words were used in.": "请选择这些单词曾用于哪种钱包。",
  "These are list words": "这些是列表单词",
  "Minima's form": "Minima 的格式",
  "Exactly as typed": "完全按输入内容",
  "A wallet made by Minima uses its own form of the words (capitals, single spaces). Older apps could make a wallet from the words exactly as they were typed. Choose \"Exactly as typed\" only for such a wallet: otherwise you open a different, empty wallet.": "由 Minima 创建的钱包使用其自身的单词格式（大写字母、单个空格）。旧版应用可以完全按输入的内容用单词创建钱包。只有这类钱包才应选择“完全按输入内容”：否则您打开的将是另一个空钱包。",
  "Enter a host:port for the custom peer.": "请为自定义对等节点输入 host:port。",
  "{keyArg} cannot be set here. The wallet's key mode sets it.": "{keyArg} 不能在此设置。它由钱包的密钥模式决定。",
  "{ownedArg} cannot be set here. The app sets it itself.": "{ownedArg} 不能在此设置。它由应用自行设置。",
  "Startup parameters": "启动参数",
  "Configure how the node starts. Changes take effect when the node restarts.": "配置节点的启动方式。更改将在节点重启后生效。",
  "On: the wallet is made with classic keys. Off (default): block key uses on a low-RAM node (-blockaskeyuses -lowram); classic mode uses more RAM.\n\nThis is chosen once, before the wallet exists, and cannot be changed afterwards. The same seed produces different addresses in each mode: to restore a wallet, choose the mode it was made in.": "开启：使用经典密钥创建钱包。关闭（默认）：在低内存节点上使用区块密钥计数（-blockaskeyuses -lowram）；经典模式会占用更多内存。\n\n此项只能在钱包创建之前选择一次，之后无法更改。同一个种子在两种模式下会生成不同的地址：恢复钱包时，请选择创建它时所用的模式。",
  "Server mode (-server)": "服务器模式（-server）",
  "Accept incoming connections instead of client-only. Needs a reachable port (router forward / hotspot).": "接受入站连接，而不只是作为客户端。需要可访问的端口（路由器端口转发／热点）。",
  "MegaMMR (-megammr)": "MegaMMR（-megammr）",
  "Keep the full Mega MMR so this node can serve seed resyncs. Uses significantly more RAM and storage.": "保留完整的 Mega MMR，使此节点能够为种子重新同步提供服务。这会使用显著更多的内存和存储空间。",
  "RPC (-rpcenable)": "RPC（-rpcenable）",
  "Always on": "始终开启",
  "HTTP RPC interface on port {rpcPort}. This app talks to its node through it, so it cannot be switched off. Anything that can reach the port can command this node, so it is never started without Basic auth: user minima, password below.": "端口 {rpcPort} 上的 HTTP RPC 接口。本应用通过它与节点通信，因此无法关闭。任何能访问此端口的程序都可以向此节点发出命令，所以它绝不会在没有 Basic 认证的情况下启动：用户名 minima，密码见下方。",
  "RPC interface on port {rpcPort}, on this computer only. This app talks to its node through it, so it cannot be switched off. The Parlons Node takes no RPC password.": "端口 {rpcPort} 上的 RPC 接口，仅限本机访问。本应用通过它与节点通信，因此无法关闭。Parlons 节点不使用 RPC 密码。",
  "Copy RPC password": "复制 RPC 密码",
  "Keets transport (-keets)": "Keets 传输（-keets）",
  "On: KeetChat and the peer-to-peer keets transport, as before. Off: no Hyperswarm sidecar and no DHT - the node runs on the classic Minima transport only and uses less RAM. Your chats and keets identity stay on this computer and return when you switch it back on. Applies after a restart.": "开启：与之前一样，使用 KeetChat 和点对点 keets 传输。关闭：不运行 Hyperswarm 辅助进程，也不使用 DHT，节点仅通过经典 Minima 传输运行，占用更少内存。您的聊天记录和 keets 身份会保留在这台电脑上，重新开启后即可恢复。重启后生效。",
  "Extra arguments (advanced)": "额外参数（高级）",
  "-p2pnodes host:port -txpowdbstore 3 …": "-p2pnodes host:port -txpowdbstore 3 …",
  "Space-separated flags passed to the node at boot, after the parameters below. Quotes are respected. -blockaskeyuses and -lowram are not allowed here: the wallet's key mode sets them.": "启动时传给节点的参数，以空格分隔，排在下方参数之后。支持引号。此处不允许使用 -blockaskeyuses 和 -lowram：它们由钱包的密钥模式决定。",
