  "Resync this node?": "重新同步此节点？",
  "Minima will rebuild its chain data from {h}.\n\n• Your wallet and seed phrase are not touched.\n• Any transaction still waiting to be mined is dropped.\n\nThis can take a while on a slow connection.": "Minima 将从 {h} 重建其链数据。\n\n• 您的钱包和助记词不会被更改。\n• 所有仍在等待打包的交易都会被丢弃。\n\n网络较慢时可能需要一些时间。",
  "Replaces this node's wallet and chain with the contents of a backup, then catches up to the chain tip from a MegaMMR node.": "用备份的内容替换此节点的钱包和链，然后从 MegaMMR 节点同步到链的最新区块。",
