  "Anyone who reads these words owns your funds. Write them down somewhere only you can reach: never in a photo, a note app or a message.": "任何看到这些单词的人都能拥有您的资金。请把它们抄写在只有您能接触到的地方：绝不要保存在照片、笔记应用或消息中。",
