  "Replace this node's wallet with the one for a seed phrase, then resync from a MegaMMR node. Destructive.": "用助记词对应的钱包替换此节点的钱包，然后从 MegaMMR 节点重新同步。此操作会覆盖现有数据。",
  "higher than any previous rebuild of this seed": "高于此种子以往任何一次重建时的数值",
