  "Node stopped": "节点已停止",
  "{n} (token {tid})": "{n}（代币 {tid}）",
  "{b}Runs entirely on this computer.{_b} Your secret key is sent only to your own local node (127.0.0.1) to derive keys and sign. It never leaves this machine and is never saved.": "{b}完全在这台电脑上运行。{_b}您的秘密密钥只会发送到您自己的本地节点（127.0.0.1），用于派生密钥和签名。它绝不会离开这台电脑，也绝不会被保存。",
  "{b}Never type your secret key into a website Web Wallet.{_b} A hosted site can steal it (that has drained wallets).": "{b}切勿在网站版 Web Wallet 中输入您的秘密密钥。{_b}托管网站可以窃取它（已有钱包因此被掏空）。",
  "Minima Web Wallet": "Minima Web Wallet",
  "Minima Web Wallet is unavailable!": "Minima Web Wallet 不可用！",
  "A -megammr node is required to use this Wallet.": "使用此钱包需要 -megammr 节点。",
  "The Web Wallet reaches a wallet from its secret key alone, so this node must keep the full MegaMMR to serve the coins and proofs of that wallet's address. Enabling MegaMMR restarts the node and grows its data over time. It is a one-time change.": "Web Wallet 仅凭秘密密钥访问钱包，因此此节点必须保留完整的 MegaMMR，才能提供该钱包地址的币和证明。启用 MegaMMR 会重启节点，其数据会随时间增长。这是一次性更改。",
  "Enable MegaMMR & restart node": "启用 MegaMMR 并重启节点",
  "Restarting node…": "正在重启节点…",
  "MegaMMR enabled. The node is restarting": "MegaMMR 已启用。节点正在重启",
  "Could not enable MegaMMR": "无法启用 MegaMMR",
  "Login with your secret key.": "使用您的秘密密钥登录。",
  "Enter a secret key": "输入秘密密钥",
  "Secret key": "秘密密钥",
  "Show the secret key": "显示秘密密钥",
  "Show": "显示",
  "24 words or your own phrase: any phrase is accepted. Enter it EXACTLY as created: capitals, spaces and hyphens (-) all count. {b}Do not share this key with anyone!{_b}": "24 个单词或您自己的短语：任何短语均可接受。请与创建时完全一致地输入：大写字母、空格和连字符（-）都算数。{b}切勿与任何人分享此密钥！{_b}",
  "Login": "登录",
  "Hide": "隐藏",
  "Enter your secret key.": "请输入您的秘密密钥。",
  "The key has a \", \\ or line break the command can't carry. Enter it as one clean line.": "密钥中含有 \"、\\ 或换行符，命令无法携带。请将其作为干净的一行输入。",
  "Logging in…": "正在登录…",
