  "Logout": "退出登录",
  "Checking the chain…": "正在检查区块链…",
  "Not confirmed: this key's on-chain uses could not be read, and a figure that is too low can lose funds. Check your connection and try again.": "未确认：无法读取此密钥的链上使用次数，而数字偏低可能导致资金丢失。请检查网络连接后重试。",
  "Secret key uses confirmed: {n}": "秘密密钥使用次数已确认：{n}",
