  "Log out of this session": "退出此会话",
  "If you haven't stored your secret key then this is your last chance! It is not kept by this app: after Logout it is gone from memory.\n\n{keyuses}": "如果您还没有保存秘密密钥，这是最后的机会！此应用不会保留它：退出登录后，它将从内存中消失。\n\n{keyuses}",
  "Secret key uses: {keyuses}\nWe recommend taking a note of your secret key uses. This should be increased each time you send a transaction.": "秘密密钥使用次数：{keyuses}\n建议您记下秘密密钥使用次数。每发送一笔交易，该数字都应增加。",
