  "Start again": "重新启动",
  "Stop contributing to the network": "停止为网络做贡献",
  "Contribute to the network": "为网络做贡献",
  "Reconfigure node": "重新配置节点",
  "Contribute to the network?\n\nYour node will accept incoming connections and help other nodes sync. This asks your router to open TCP {basePort} (UPnP), keeps ~50 days of block history (a one-time extra download), and restarts the node now.\n\nNot all routers allow this. If yours doesn't, you'll still help by relaying.": "为网络做贡献？\n\n您的节点将接受入站连接，并帮助其他节点同步。这会请求路由器打开 TCP {basePort}（UPnP），保留约 50 天的区块历史（一次性的额外下载），并立即重启节点。\n\n并非所有路由器都允许这样做。如果您的路由器不允许，您仍可通过转发提供帮助。",
  "Stop contributing?\n\nYour node goes back to a light wallet (outbound connections only), the router port is closed, and the node restarts now.": "停止贡献？\n\n您的节点将变回轻钱包（仅出站连接），路由器端口将关闭，节点将立即重启。",
  "Contribute to the network?": "为网络做贡献？",
  "Stop contributing?": "停止贡献？",
