  "v{appversion}  ·  node-derived{ewAt}": "v{appversion}  ·  由节点派生{ewAt}",
  "·  updated {ewAt}": "·  更新于 {ewAt}",
  "The node is not running. Start it on the Node tab, then come back: this wallet sets itself up.": "节点未运行。请在“节点”标签页启动它，然后返回：此钱包会自行完成设置。",
  "Dexicon is frozen. Unfreeze it on the Apps tab to use this wallet.": "Dexicon 已冻结。请在“应用”标签页解冻它，才能使用此钱包。",
  "Setting up wallet…": "正在设置钱包…",
  "The key is derived from this node (the same one Dexicon ① MxUSD swaps with). The node must be running and unlocked.": "密钥由此节点派生（与 Dexicon ① MxUSD 兑换所用的是同一个）。节点必须正在运行且已解锁。",
  "↻  Refresh": "↻  刷新",
  "Retrying…": "正在重试…",
  "Not read yet": "尚未读取",
  "Options for {menu}": "{menu} 的选项",
  "Token options": "代币选项",
  "⚠ Dexicon ① MxUSD is halted: this node's keys are not the ones it saved. Read its notice before sending anything from here.": "⚠ Dexicon ① MxUSD 已停止：此节点的密钥不是它保存的那些。从这里发送任何资金之前，请先阅读它的通知。",
  "Your address  ·  click to receive": "您的地址  ·  点击接收",
  "Ethereum": "以太坊",
  "⚠ RPC: the Ethereum endpoints did not answer. Refresh, or set another one in Settings.": "⚠ RPC：以太坊端点没有响应。请刷新，或在“设置”中设定另一个端点。",
  "↑  Send": "↑  发送",
