  "Refreshing…": "正在刷新…",
  "Same address on all EVM networks. Send only Ethereum-mainnet assets here.": "所有 EVM 网络使用相同地址。请仅向此地址发送 Ethereum 主网资产。",
  "Address copied": "地址已复制",
