  "Estimating fee…": "正在估算手续费…",
  "Token: {label}  (click to change · balance {bal})": "代币：{label}  （点击更改 · 余额 {bal}）",
  "Send which token": "选择要发送的代币",
  "Scan recipient address": "扫描收款地址",
  "Reserving gas…": "正在预留 Gas…",
  "⚠ Could not check whether a Dexicon ① MxUSD swap is in flight. Swaps sign with this same address and need its ETH for gas: look at Dexicon, Activity before sending.": "⚠ 无法检查是否有 Dexicon ① MxUSD 兑换正在进行。兑换使用同一地址签名，并需要其中的 ETH 支付 Gas：发送前请查看 Dexicon 的“活动”。",
  "⚠ {k} in flight. {k2} with this same address and {k3} ETH here for gas to claim or refund. Sending ETH out now can leave a swap unable to finish before its time limit. Wait until Dexicon, Activity shows {k4} finished, or leave enough ETH for gas.": "⚠ {k}正在进行。{k2}使用的是同一地址，并且{k3}这里的 ETH 支付 Gas 才能领取或退款。现在转出 ETH 可能导致兑换无法在时限前完成。请等到 Dexicon 的“活动”显示{k4}已完成，或留下足够的 ETH 支付 Gas。",
  "1 swap of Dexicon ① MxUSD is": "有 1 笔 Dexicon ① MxUSD 兑换",
  "{k} swaps of Dexicon ① MxUSD are": "有 {k} 笔 Dexicon ① MxUSD 兑换",
  "It signs": "它签名",
  "They sign": "它们签名",
