  "On the desktop this wallet always uses the embedded wallet: the key this node derives, which is also the key Dexicon ① MxUSD swaps sign with.": "在桌面版中，此钱包始终使用内置钱包：即此节点派生的密钥，它也是 Dexicon ① MxUSD 兑换签名所用的密钥。",
  "Importing another key is not offered here. One Ethereum key serves this wallet and the swaps, and replacing it while a swap is in flight would leave that swap unable to claim or refund. (Nothing here moves funds.)": "这里不提供导入其他密钥。同一个以太坊密钥同时用于此钱包和兑换，在兑换进行期间更换它，会使该兑换无法领取或退款。（此处的操作不会转移资金。）",
  "Anyone who sees this key can take these funds, permanently and irreversibly. Only continue if you are alone and know exactly why you need it.": "任何看到此密钥的人都能永久转走资金，无法撤销。仅在独处且明确了解用途时继续。",
  "It is also the key Dexicon ① MxUSD swaps sign with.": "它也是 Dexicon ① MxUSD 兑换签名所用的密钥。",
