  "Parlons opens in your browser, signed in to the account on this node. Each time, the app asks the node for a new one-time link, and only for this computer.": "Parlons 会在您的浏览器中打开，并已登录此节点上的账户。每次打开时，应用都会向节点请求一个新的一次性链接，且仅供这台电脑使用。",
  "Open Parlons in the browser": "在浏览器中打开 Parlons",
  "Your Parlons address": "您的 Parlons 地址",
  "While the node runs, this app tells you when a Parlons message arrives. It tells you of an incoming call only while Parlons is open in a browser tab or a paired phone is in reach: with neither, the node declines the call at once and tells nothing. Calls are answered in the Parlons tab.": "节点运行期间，此应用会在收到 Parlons 消息时通知您。只有当 Parlons 在浏览器标签页中打开，或有已配对的手机可连接时，它才会通知您有来电：两者都没有时，节点会立即拒接来电，且不作任何通知。来电在 Parlons 标签页中接听。",
