  "The archive shows more spend blocks than the stored classic counter. Review these keys before signing again. Block-based leaf positions are not compared with spend counts.": "档案显示的支出区块数超过已存储的经典计数器。再次签名前请复核这些密钥。区块密钥的叶位置不会与支出次数比较。",
  "Common causes": "常见原因",
  "No known key reuse was found in the checked keys.": "在已检查的密钥中未发现已知的重复使用。",
  "Audit needs review": "审计需要复核",
  "Some public audit results are missing or inconsistent. Those rows remain unknown. Confirmed reuse findings still apply.": "部分公开审计结果缺失或不一致。这些行仍标记为未知。已确认的重复使用结果仍然有效。",
  "Each one-time signing leaf must sign only once. Classic keys use counters; block-based keys use block-derived positions. The audit combines archive spend counts with witnessed reuse reports for both families. USED/UNUSED describes the archive history; it does not verify a local signing counter.": "每个一次性签名叶只能签名一次。经典密钥使用计数器；区块密钥使用由区块确定的位置。审计会将归档的支出次数与两类密钥的见证重复使用报告结合起来。已使用/未使用描述的是归档历史；它不会验证本地签名计数器。",
  "Node seed · block-based": "节点种子 · 区块",
  "Block-based keys use a block-derived leaf position. A classic keyuses recovery estimate does not apply to these keys.": "区块密钥使用由区块确定的叶位置。经典 keyuses 恢复估值不适用于这些密钥。",
  "Classic recovery estimate: review before use": "经典恢复估值：使用前请复核",
  "Key audit": "密钥审计",
  "The server’s address differs from the locally derived address. Treat the audit as incomplete.": "服务器地址与本地派生地址不同。此审计不完整。",
  "A key is near its signature capacity. Review it before signing again.": "某个密钥接近签名容量上限。再次签名前请复核。",
  "Not checked here: the keys this wallet's seed gives in the other key mode (the phone checks 64 classic and 32 block-based keys derived from the seed), and minimaWallet's keys. If this seed was ever used in the other mode or in another wallet app, those keys can have been reused and this result does not show it.": "此处未检查：此钱包的种子在另一种密钥模式下生成的密钥（手机会检查从种子派生的 64 个经典密钥和 32 个区块密钥），以及 minimaWallet 的密钥。如果此种子曾在另一种模式或其他钱包应用中使用过，那些密钥可能已被重复使用，而此结果不会显示。",
  "The node’s keys could not be read. Check that the node is running, then run the audit again.": "无法读取节点的密钥。请检查节点是否正在运行，然后重新运行审计。",
  "Not read": "未读取",
  "Classic keys: most-used key": "经典密钥：使用最多的密钥",
  "{used} of {cap} signatures · {count}": "已用 {used} / {cap} 次签名 · {count}",
  "A classic signing key is {pct}% used. Generate fresh keys or restore with the correct key uses before it is exhausted.": "某个经典签名密钥已使用 {pct}%。请在它耗尽之前生成新密钥，或使用正确的密钥使用次数进行恢复。",
  "Block-based keys: key block position": "区块密钥：密钥区块位置",
  "A block-based key's position follows the chain's block number. It is not a count of signatures, so it is not compared with classic keys.": "区块密钥的位置跟随链的区块号。它不是签名次数，因此不与经典密钥比较。",
  "REUSED{reuseCount}": "已重复使用{reuseCount}",
  "AT RISK": "存在风险",
  "Unknown": "未知",
  "USED {sigs}": "已使用 {sigs}",
  "UNUSED": "未使用",
  "The witness index reports repeated use of a one-time key; maximum reported depth: {worstReuse}. Review the affected addresses before further use.": "见证索引报告了一次性密钥重复使用；报告的最大次数：{worstReuse}。继续使用前请复核受影响的地址。",
  "Blocks-as-keyuses keys": "区块用作使用次数的密钥",
  "✓ on chain · block {block} · confirmations: {confirmations}": "✓ 已上链 · 区块 {block} · 确认数：{confirmations}",
  "not found on chain (mempool or pruned)": "链上未找到（在内存池中或已修剪）",
  "Click to copy": "点击复制",
  "Address (click to copy)": "地址（点击复制）",
  "Local uses": "本地使用次数",
  "Spend blocks": "支出区块数",
  "Spent coins": "已花费币",
  "{tip} Spend blocks can undercount signatures. Only default addresses are checked; custom scripts and multisig usage are not included. A clear result is not proof that a key is safe.": "{tip}支出区块数可能少于签名次数。仅检查默认地址，不包括自定义脚本和多重签名的使用。未发现问题不代表密钥一定安全。",
  "Archive coverage to block {tip}.": "档案覆盖至区块 {tip}。",
  "The archive did not say which block it reaches.": "档案未说明覆盖到哪个区块。",
  "Check the keys this node holds for one-time signature reuse: classic keys and block-based keys, whichever this wallet has.": "检查此节点持有的密钥是否重复使用了一次性签名：经典密钥和区块密钥，以此钱包拥有的为准。",
  "Start the node on the Node tab, then run the audit.": "请先在“节点”标签页启动节点，再运行审计。",
  "Auditing your keys…": "正在审计密钥…",
  "Run audit": "运行审计",
  "Only public keys and addresses are sent to eurobuddha.com for the audit. This reveals the selected addresses to that server. Seeds stay on this computer.": "审计时仅将公钥和地址发送到 eurobuddha.com。该服务器会因此得知所选地址。种子保留在这台电脑上。",
  "On this computer the audit covers the keys the node holds. The phone also checks the 64 classic and 32 block-based keys it derives from the seed, and minimaWallet’s keys; that is not done here.": "在这台电脑上，审计涵盖节点持有的密钥。手机还会检查从种子派生的 64 个经典密钥和 32 个区块密钥，以及 minimaWallet 的密钥；这里不做这些检查。",
  "eurobuddha · Minima Ecosystem · KeyUses": "eurobuddha · Minima 生态 · KeyUses",
