  "Block № · TxPoW ID · 0x / Mx address": "区块号 · TxPoW ID · 0x / Mx 地址",
  "Block number, TxPoW ID or address": "区块号、TxPoW ID 或地址",
  "Search": "搜索",
  "Node unavailable": "节点不可用",
  "The node's answer did not match; this roll was not used.": "节点的应答不一致；此次掷骰未被使用。",
  "The node's answer did not match; no word was picked. Try again.": "节点的应答不一致；未选出任何词。请重试。",
  "BIP39 self-test ✓ node SHA3 + device CSPRNG verified": "BIP39 自检 ✓ 节点 SHA3 + 设备 CSPRNG 已验证",
  "{ennodebad}: device CSPRNG only (single source)": "{ennodebad}：仅使用设备 CSPRNG（单一熵源）",
  "the node's answers did not match": "节点的应答不一致",
  "node commands failed": "节点命令执行失败",
  "Auto-roll: on": "自动掷骰：开启",
