  "MARKET HISTORY · PRICE ONLY": "市场历史 · 仅价格",
  "last {price} · {ex} filled · {op} open. Every swap this node saw on the book, no back-fill. The list is in Activity › Market history.": "最新价 {price} · 已成交 {ex} · 未结 {op}。此节点在订单簿上见到的每笔兑换，不回补历史。列表在 活动 › 市场历史。",
  "Collecting market data…": "正在收集市场数据…",
  "Your order · USDT ⇄ {cc}": "您的订单 · USDT ⇄ {cc}",
  "Peg → {src}": "锚定 → {src}",
  "fetching {src} price…": "正在获取 {src} 价格…",
  "Pegged: prices follow the {src} mid. Size fills every rung; any amount or price can be edited. Only the chosen number of levels is published.": "已锚定：价格跟随 {src} 中间价。“数量”会填入每个档位；任何数量或价格都可以编辑。只发布所选数量的档位。",
  "BIDS · you buy {cc}": "买盘 · 您买入 {cc}",
  "ASKS · you sell {cc}": "卖盘 · 您卖出 {cc}",
  "amount · price": "数量 · 价格",
  "price · amount": "价格 · 数量",
  "Min trade · {cc}": "最小交易量 · {cc}",
  "Save & publish": "保存并发布",
  "Withdraw market": "撤回市场",
  "Close the editor": "关闭编辑器",
  "BIDS  {bids}\nASKS  {asks}": "买盘  {bids}\n卖盘  {asks}",
  "{ccy} · mid {mid}{fresh}{wide}": "{ccy} · 中间价 {mid}{fresh}{wide}",
  "· WIDE": "· 价差过宽",
  "waiting for {source} price…": "正在等待 {source} 价格…",
  "Halted: this node no longer owns the keys AtomiX uses here. Nothing was published.": "已暂停：此节点已不再拥有 AtomiX 在此使用的密钥。未发布任何内容。",
  "Saving…": "正在保存…",
  "Negotiate a custom size and price directly with a liquidity provider (LP), then settle as the same trustless HTLC swap as everything else in ①: each side locks, the secret releases both, and a stalled deal refunds. Go live with your own availability and other people can propose deals to you; this app answers and settles while it is running.": "直接与流动性提供方（LP）协商自定义的数量和价格，然后与 ① 中的其他交易一样，以同样无需信任的 HTLC 兑换进行结算：双方各自锁定，密文同时释放两侧，停滞的交易会退款。将您自己的可交易额度上线后，其他人即可向您提出交易；此应用运行期间会应答并结算。",
  "OTC — A PRIVATE DEAL": "OTC — 私下交易",
  "MY AVAILABILITY": "我的可交易额度",
  "I SELL up to": "我卖出，最多",
  "max {c} (blank = off)": "最多 {c}（留空即关闭）",
  "I BUY up to": "我买入，最多",
  "● Live: LPs can negotiate with you": "● 在线：LP 可与您协商",
  "○ Off": "○ 已关闭",
  "Update": "更新",
  "Go live": "上线",
  "LIQUIDITY PROVIDERS": "流动性提供方",
  "Reading the OTC board…": "正在读取 OTC 公告板…",
  "No OTC LPs online right now.": "目前没有在线的场外交易流动性提供方。",
  "LP id": "LP ID",
  "MY DEALS": "我的交易",
  "No OTC deals yet.": "尚无场外交易。",
  "{side}{amount} {c} @ {price} USDT": "{side}{amount} {c} @ {price} USDT",
  "LP sells": "LP 卖出",
  "LP buys": "LP 买入",
  "Accept": "接受",
  "Counter": "还价",
  "Reject": "拒绝",
  "{ccy} amount{cap}": "{ccy} 数量{cap}",
  "(at most {cap})": "（最多 {cap}）",
  "Price (USDT per {ccy})": "价格（每 {ccy} 的 USDT）",
  "That LP's offer changed or left the board while this screen was open. Nothing was sent. The list is redrawn: look again.": "此界面打开期间，该 LP 的报价已更改或已离开公告板。未发送任何内容。列表已重新绘制：请再看一遍。",
  "{c} This sends an offer only: nothing is locked until the LP accepts and the swap starts.\n\nLP id\n{cid}": "{c} 这只会发送一份报价：在 LP 接受且兑换开始之前不会锁定任何资金。\n\nLP ID\n{cid}",
  "You buy {c} from this LP and pay USDT on Ethereum.": "您从此 LP 买入 {c}，并在以太坊上支付 USDT。",
  "You sell {c} to this LP and receive USDT on Ethereum.": "您向此 LP 卖出 {c}，并在以太坊上收到 USDT。",
  "Send offer": "发送报价",
  "Your counter replaces the terms on the table. Nothing is locked until one side accepts.": "您的还价会取代当前谈判中的条款。在一方接受之前不会锁定任何资金。",
  "Send counter": "发送还价",
  "This screen of the room is not built in this version yet.": "此版本尚未包含该房间的这个界面。",
  "About AtomiX": "关于 AtomiX",
  "Swap MINIMA or MxUSD ⇄ Ethereum USDT trustlessly across chains: no middleman ever holds your funds. Both sides lock their funds in a time-locked contract; a swap that stalls is refunded by itself at its deadline.\n\nYour keys are derived from this node's seed, so it is the same wallet and identity on any device running AtomiX on this node's seed.\n\nRoom ① has Swap (a quick trade), Market (the order book and your own offer) and OTC (private negotiated deals). Your swaps are in Activity and History, your Ethereum wallet in Assets.\n\nAtomiX trades on the same on-chain books as the AtomiX phone app and MiniDapp.": "无需信任地跨链兑换 MINIMA 或 MxUSD ⇄ 以太坊 USDT：任何中间人都不会持有您的资金。双方都把资金锁在带时间锁的合约中；停滞的兑换会在其截止时间自行退款。\n\n您的密钥由此节点的种子派生，因此在任何以此节点种子运行 AtomiX 的设备上，都是同一个钱包和身份。\n\n房间 ① 包含“兑换”（快速交易）、“市场”（订单簿和您自己的报价）和 OTC（私下协商的交易）。您的兑换在“活动”和“历史记录”中，您的以太坊钱包在“资产”中。\n\nAtomiX 与 AtomiX 手机应用和 MiniDapp 在相同的链上订单簿上交易。",
  "ETHEREUM": "以太坊",
  "AtomiX is still starting: the Ethereum wallet appears when it is ready.": "AtomiX 仍在启动：以太坊钱包就绪后会显示。",
  "The node is stopped. The Ethereum wallet appears when it runs.": "节点已停止。节点运行后会显示以太坊钱包。",
