  "This token is not MxUSD. Its name imitates it.": "此代币不是 MxUSD。它的名称在仿冒 MxUSD。",
  "The pair you had selected is no longer in the pool registry (token {tok}). Nothing was sent and no other pair was selected for you. Pick a pair.": "您之前选择的交易对已不在池注册表中（代币 {tok}）。未发送任何内容，也没有为您选择其他交易对。请选择一个交易对。",
  "{pairName}   ·   {pools}   ·   depth {depth} MINIMA": "{pairName}   ·   {pools}   ·   深度 {depth} MINIMA",
