  "Market ≈ {mid} USDT/MINIMA (MEXC)  ·  Pool {spot}  ·  {word}": "市场 ≈ {mid} USDT/MINIMA（MEXC）  ·  池 {spot}  ·  {word}",
  "PandaPools is still starting. One moment.": "PandaPools 仍在启动。请稍候。",
  "This trade is too large for the pools' depth. Try a smaller amount.": "此交易超出池的流动性深度。请尝试较小的数量。",
  "Price impact": "价格影响",
  "Routed across": "路由经过",
  "{poolsUsed} of {poolsAvailable} pools{maxPools}": "{poolsAvailable} 个池中的 {poolsUsed} 个{maxPools}",
  "(top {maxPools})": "（前 {maxPools} 个）",
  "Pool fee (0.50%)": "池手续费（0.50%）",
  "You receive": "您收到",
  "Confirm swap": "确认兑换",
  "Pay  {routed} {pay}{amt}\nReceive  {totalOut} {get}\nRate  ≈ {effPrice} {name} / MINIMA\nPool pair  {pairName}{imitates}\n\nPrice impact {priceImpact}%.{poolsUsed}\n\nThis posts a real on-chain transaction for exactly these amounts. There is no slippage setting: if a pool moves before it confirms, the swap is rejected and you keep your funds.": "支付  {routed} {pay}{amt}\n收到  {totalOut} {get}\n汇率  ≈ {effPrice} {name} / MINIMA\n池交易对  {pairName}{imitates}\n\n价格影响 {priceImpact}%。{poolsUsed}\n\n这会按这些确切金额发布一笔真实的链上交易。没有滑点设置：如果池在交易确认前发生变动，兑换会被拒绝，您的资金仍归您所有。",
  "(you typed {amt}; this is the amount the pools take)": "（您输入的是 {amt}；这是池实际接受的数量）",
  "Routed across {poolsUsed} pools in one transaction.": "在一笔交易中路由经过 {poolsUsed} 个池。",
  "{pools} · {zero} MINIMA aggregate depth": "{pools} · 合计深度 {zero} MINIMA",
  "{reserveM} MINIMA  ·  {reserveT} {name}": "{reserveM} MINIMA  ·  {reserveT} {name}",
