  "File read. Nothing is restored yet: press Restore.": "文件已读取。尚未恢复任何内容：请按“恢复”。",
  "Node restore password": "节点恢复密码",
  "Show restore password": "显示恢复密码",
  "Restoring: checking each pool's reserves on this node…": "正在恢复：正在此节点上检查每个池的储备…",
