  "The dialog was closed before the archive setting had answered, so it is not known yet whether it was saved. Open Archive connection again to see.": "归档设置尚未应答时对话框就被关闭了，因此尚不知道是否已保存。请再次打开“归档连接”查看。",
  "Collect withdrawn funds to my wallet": "将已提现资金收集到钱包",
