  "Building the statement: the transaction history is being caught up with the node. This can take a while.": "正在生成报表：正在与节点同步交易历史记录。这可能需要一些时间。",
  "That pool is no longer in the list. Nothing was sent.": "该池已不在列表中。未发送任何内容。",
  "Checking local reserves and current archive proofs. No transaction is signed.": "正在检查本地储备和当前归档证明。不会签署任何交易。",
  "Switch Dexicon to its light theme": "将 Dexicon 切换为浅色主题",
  "Switch Dexicon to its dark theme": "将 Dexicon 切换为深色主题",
  "Dexicon stopped before it answered. Look at Activity before trying again.": "Dexicon 在应答之前就停止了。重试之前请先查看“活动”。",
