  "The balance could not be read.": "无法读取余额。",
  "The node is stopped, so nothing here can trade. Start it and Dexicon comes back by itself.": "节点已停止，因此此处无法进行任何交易。启动节点后，Dexicon 会自行恢复。",
  "Dexicon is still starting: it is reading this wallet's trading identity from the node. Nothing can be sent yet.": "Dexicon 仍在启动：它正在从节点读取此钱包的交易身份。目前还不能发送任何内容。",
  "The trading identity could not be read: {idError}": "无法读取交易身份：{idError}",
  "Dexicon is still starting. Nothing can be sent yet.": "Dexicon 仍在启动。目前还不能发送任何内容。",
  "No relay is set, so there is no FAST book and a FAST order cannot be published. Add a relay in Settings.": "未设置中继，因此没有 FAST 订单簿，也无法发布 FAST 订单。请在“设置”中添加中继。",
  "No relay answers right now, so the FAST book may be out of date and a FAST order may not be heard. On-chain orders and pools still work.": "目前没有中继应答，因此 FAST 订单簿可能已过时，FAST 订单也可能无法被收到。链上订单和池仍可使用。",
