  "{minima} MINIMA  ·  {mxusd} MxUSD  available": "{minima} MINIMA  ·  {mxusd} MxUSD  可用",
  "Available: … ({balErr})": "可用：…（{balErr}）",
  "Available: {buy}{buy2}  ·  tap for max\n({minima} MINIMA · {mxusd} MxUSD in wallet)": "可用：{buy}{buy2}  ·  点击使用最大值\n（钱包中有 {minima} MINIMA · {mxusd} MxUSD）",
