  "You pay {amount} MINIMA\nYou receive at least {all} MxUSD": "您支付 {amount} MINIMA\n您至少收到 {all} MxUSD",
  "Nothing can be taken in this amount": "此数量下没有可吃的订单",
  "Fills now ≈ {take} MINIMA @ avg {avg}": "立即成交 ≈ {take} MINIMA @ 均价 {avg}",
  "Nothing crosses on the FAST book: all of it rests as your FAST order @ {price}": "FAST 订单簿上无法成交：全部作为您的 FAST 订单挂出 @ {price}",
  "Exceeds your free {buy} by {short} (free {free})": "超出您可用的 {buy}，超出 {short}（可用 {free}）",
  "Crosses FAST orders → the button IS the trade: one click takes them best-first up to your amount, no dialog, progress in the log below; what they can't cover is not traded. BOOK/POOL on-chain liquidity still shows a confirm. Nothing crosses → rests on the relays as your FAST order.": "会与 FAST 订单成交 → 按钮即是交易：一次点击按最优价依次吃单，直到您的数量，无需对话框，进度显示在下方日志中；它们无法覆盖的部分不会成交。BOOK/POOL 链上流动性仍会显示确认。没有可成交的 → 作为您的 FAST 订单挂在中继上。",
  "{take} NOW · FAST": "立即{take} · FAST",
  "instant ·": "即时 ·",
