  "The book moved. Review again": "订单簿已变动。请重新查看确认",
  "Review this on-chain trade": "查看确认这笔链上交易",
  "{asked}\n\nYour node signs this transaction and posts it. It is final only when a block confirms it (about 3 minutes); until then Activity shows it as waiting.": "{asked}\n\n您的节点会签署并提交这笔交易。只有区块确认后（约 3 分钟）它才最终完成；在此之前，“活动”中显示为等待中。",
  "Sign and send": "签署并发送",
  "Nothing was signed or sent.": "未签署或发送任何内容。",
  "No open orders": "没有未结订单",
  "FAST · order {orderId}": "FAST · 订单 {orderId}",
  "{pending} WAITING FOR A BLOCK": "{pending} 等待区块",
  "ON-CHAIN · coin {coinid}": "链上 · 币 {coinid}",
  "ON-CHAIN · posted, waiting for a block: not on the book yet": "链上 · 已提交，等待区块：尚未进入订单簿",
  "Change the price of this order": "更改此订单的价格",
  "Cancel this order": "取消此订单",
  "Cancel this order?": "取消此订单？",
  "FAST order {id}\n\nYour node signs a cancel and sends it to every relay. Nothing moves on the chain: the coins never left your wallet. A take that a maker already co-signed still settles.": "FAST 订单 {id}\n\n您的节点会签署一条取消指令并发送给每一个中继。链上没有任何变动：这些币从未离开您的钱包。做市方已联合签名的吃单仍会结算。",
  "On-chain order, coin {id}\n\nYour node signs a transaction that returns the order's locked funds to your wallet. The order can still be filled until a block confirms the cancel.": "链上订单，币 {id}\n\n您的节点会签署一笔交易，将订单锁定的资金退回您的钱包。在区块确认取消之前，该订单仍可能被成交。",
  "Cancel the order": "取消订单",
  "New price": "新价格",
  "{id}\n\nMxUSD per MINIMA:": "{id}\n\n每 MINIMA 的 MxUSD 数：",
  "FAST order {id}\n\nYour node signs the order again at the new price and sends it to every relay. Nothing moves on the chain.": "FAST 订单 {id}\n\n您的节点会按新价格重新签署订单并发送给每一个中继。链上没有任何变动。",
  "On-chain order, coin {id}\n\nYour node signs a transaction that moves the order to the new price. The old price can still be filled until a block confirms it.": "链上订单，币 {id}\n\n您的节点会签署一笔交易，将订单改为新价格。在区块确认之前，旧价格仍可能被成交。",
  "Sign the new price": "签署新价格",
  "New price, MxUSD per MINIMA": "新价格，每 MINIMA 的 MxUSD 数",
  "Enter a valid new price. Nothing was changed.": "请输入有效的新价格。未做任何更改。",
