  "signed and sent; waiting for the maker to co-sign{sent}. Not traded yet: it is voided by itself if the maker never answers.": "已签署并发送；等待做市方联合签名{sent}。尚未成交：如果做市方始终不应答，它会自行作废。",
  "· sent {sent}": "· 发送于 {sent}",
