  "{buy}{filled} MINIMA @ {price}": "{buy}{filled} MINIMA @ {price}",
  "{buy}{size} MINIMA @ {price}": "{buy}{size} MINIMA @ {price}",
  "{timems}   ON-CHAIN {maker}   {sourcekind}": "{timems}   链上 {maker}   {sourcekind}",
  "MAKER": "做市",
  "TAKER": "吃单方",
  "Every trade this node made on the Exchange, newest first, then every finished AtomiX swap of the market the ⇄ pill is on. One line each: click a line for the amounts, the block and the full on-chain identifiers. Net counts settled trades only. A trade that is co-signed and posted shows as waiting until a block holds it. The txpow id is the pre-mining id; settlement is proven by the output coins. Export CSV saves every fill for your accounts; AtomiX swaps have their own file in Activity.": "此节点在交易所完成的每一笔交易，最新在前，随后是 ⇄ 按钮所选市场中每一笔已完成的 AtomiX 兑换。每笔一行：点击某一行可查看数量、区块和完整的链上标识符。净额只统计已结算的交易。已联合签名并提交的交易在区块收录之前显示为等待中。txpow id 是挖矿前的 id；结算以输出币为证。“导出 CSV”会保存每一笔成交，供您记账；AtomiX 兑换在“活动”中有单独的文件。",
  "About History": "关于历史记录",
  "NET · SETTLED TRADES": "净成交 · 已结算",
  "{done} settled": "{done} 已结算",
  "fill ·": "笔成交 ·",
  "fills ·": "笔成交 ·",
  "No fills yet.": "暂无成交。",
  "Export CSV": "导出 CSV",
  "Bought": "已买入",
  "Sold": "已卖出",
  "{f} MxUSD → {filled} MINIMA": "{f} MxUSD → {filled} MINIMA",
  "{filled} MINIMA → {f} MxUSD": "{filled} MINIMA → {f} MxUSD",
  "{filled} MINIMA at {price} MxUSD per MINIMA": "{filled} MINIMA，价格为每 MINIMA {price} MxUSD",
  "State: {chip}, {fs}": "状态：{chip}，{fs}",
  "When: {ts}": "时间：{ts}",
  "Your side: {role}": "您的角色：{role}",
  "maker (your FAST order was taken)": "挂单方（您的 FAST 订单被吃单）",
  "taker (you took a FAST order)": "吃单方（您吃了一个 FAST 订单）",
  "Saved {fills} fills.": "已保存 {fills} 笔成交。",
  "Stop the market maker?": "停止做市？",
  "Your node signs a cancel for every ladder order and sends it to the relays within seconds. Your settings are kept. A take a maker already co-signed still settles.": "您的节点会为每一个阶梯订单签署取消指令，并在数秒内发送给中继。您的设置会保留。做市方已联合签名的吃单仍会结算。",
  "Every BUY and SELL you make and every fill your node co-signs, newest first, with its live progress. A trade is DONE (FAST) or CONFIRMED (on-chain) only when a block holds its output coin and three more blocks are on top; until then the line says where it stands. Click a line for its facts and identifiers. Market history is every fill this node saw on the book. AtomiX swaps are listed first, each with its steps, Check now and, when one is due, Refund now; a swap is never cancelled by hand: one that stalls is refunded by itself at its deadline. Pool operations (swaps against pools, creating, adding, migrating and closing a pool) follow, each with its transaction id whole; room ② Activity has the same list and every pool's transactions.": "您的每一笔买入和卖出，以及您的节点联合签名的每一笔成交，最新在前，并显示实时进度。只有当区块收录了交易的输出币并且其上又有三个区块时，交易才算“完成”（FAST）或“已确认”（链上）；在此之前，该行会说明当前进展。点击某一行可查看其详情和标识符。“市场历史”是此节点在订单簿上看到的每一笔成交。AtomiX 兑换列在最前，每笔都带有其步骤、“立即检查”，以及到期时的“立即退款”；兑换绝不会被手动取消：停滞的兑换会在截止时间自行退款。池操作（与池兑换、创建池、添加、迁移和关闭池）随后列出，每项都带有完整的交易 id；② 号房间的“活动”中有相同的列表以及每个池的交易。",
  "About Activity": "关于活动",
  "My activity": "我的活动",
  "Market history": "市场历史",
  "↓ Export CSV": "↓ 导出 CSV",
  "↓ AtomiX swaps CSV": "↓ AtomiX 兑换 CSV",
  "Nothing yet": "暂无内容",
  "Every BUY and SELL you make, every fill your node co-signs, every AtomiX swap and every pool operation shows its live progress here.": "您的每一笔买入和卖出、您的节点联合签名的每一笔成交、每一笔 AtomiX 兑换和每一项池操作，都会在此显示实时进度。",
  "{minima} MINIMA @ {price}": "{minima} MINIMA @ {price}",
