  "RECEIVE MINIMA OR MxUSD": "接收 MINIMA 或 MxUSD",
  "The address appears when Dexicon has read the chain.": "Dexicon 读取链之后，地址才会显示。",
  "YOUR TRADING ID": "您的交易 ID",
  "Not read yet.": "尚未读取。",
  "Other traders see this ID when you trade on the fast book. It is made from your node's seed, so it stays the same if you reinstall. It is not an address: never send coins to it.": "您在 FAST 订单簿上交易时，其他交易者会看到此 ID。它由您节点的种子生成，因此重新安装后保持不变。它不是地址：切勿向它发送币。",
  "OK ·": "正常 ·",
  "ERROR · {meta}": "错误 · {meta}",
  "WALLET": "钱包",
  "Dexicon trades with this node's own wallet: the node signs every trade with its own keys. Your node's seed phrase backs up everything here.": "Dexicon 使用此节点自己的钱包进行交易：节点用自己的密钥签署每一笔交易。您节点的助记词可备份此处的一切。",
  "ADD RELAY": "添加中继",
  "A Dexicon relay is the dexrelay cape of parlons-node.jar / maxima-server.jar. Orders are published to EVERY relay here; the book is the union. On the desktop a relay must be an https address.": "Dexicon 中继是 parlons-node.jar / maxima-server.jar 的 dexrelay 组件。订单会发布到此处的每一个中继；订单簿是它们的并集。在桌面版上，中继必须是 https 地址。",
