  "Walk back through the chain for messages that arrived while this app was closed": "沿链向前回溯，查找本应用关闭期间收到的邮件",
  "How delivery works": "邮件如何送达",
  "Messages travel as coins — next block, ~1–3 min": "邮件通过链上币传递，下个区块送达，约 1–3 分钟",
  "Version": "版本",
  "minimaCore Desktop": "minimaCore Desktop",
  "Failed — retry from Outbox": "失败，请从发件箱重试",
  "No messages yet — say hi.": "暂无消息，打个招呼吧。",
  "Mail can publish your six-word address so that people can write to you from the words alone.\n\n": "Mail 可以发布您的六词地址，这样别人只凭这些词就能给您写信。\n\n",
  "What is published: your six words, your Mail key and a signature, in a coin on the Minima chain (it costs 0.000000001 MINIMA, and is renewed when needed).\n\n": "发布的内容：您的六个地址词、您的 Mail 密钥和一个签名，保存在 Minima 链上的一个币中（费用为 0.000000001 MINIMA，并在需要时续期）。\n\n",
  "The coin is paid from one of your wallet's addresses, so it links your Mail address to that wallet address for anyone who looks.\n\n": "这个币由您钱包的某个地址支付，因此任何查看的人都能把您的邮件地址与该钱包地址联系起来。\n\n",
  "If you choose \"Don't publish\", people need your contact link or Mail key to write to you. You can change this later under Your key.": "如果选择“不发布”，别人需要您的联系人链接或 Mail 密钥才能给您写信。之后可以在“您的密钥”中更改此设置。",
  "Publish your Mail address?": "发布您的邮件地址？",
  "Don't publish": "不发布",
  "This key was found on chain from the six words. It is not one of your contacts and you have not written to it before.\n\n{block}A beacon published very recently deserves more care.": "此密钥是根据六个地址词在链上找到的。它不是您的联系人，您以前也没有给它写过信。\n\n{block}对于刚刚发布不久的信标，应当更加小心。",
  "Its address beacon was first seen by this node at block {first} ({first2} ago, {first3} blocks){block}.": "此节点首次看到其地址信标是在区块 {first}（{first2}前，{first3} 个区块）{block}。",
  ", last renewed at block {block}": "，最近一次续期在区块 {block}",
  "This node could not tell how old its address beacon is.": "此节点无法判断其地址信标存在了多久。",
  "This key is known only from mail it sent you. It is not one of your contacts and you have not written to it before.": "此密钥仅来自它发给您的邮件。它不是您的联系人，您以前也没有给它写过信。",
  "{how}\n\nSix words can be imitated by another key. Check the whole Mail key with the person, by another way, before you send:\n\n{key}": "{how}\n\n六个地址词可能被另一个密钥仿冒。发送前，请通过其他途径与对方核对完整的 Mail 密钥：\n\n{key}",
