  "Get Address": "获取地址",
  "Minima History": "Minima 历史记录",
  "History options": "历史记录选项",
  "Export as JSON (backup)": "导出为 JSON（备份）",
  "Export as CSV (spreadsheet)": "导出为 CSV（电子表格）",
  "Import history (restore / merge)": "导入历史记录（恢复 / 合并）",
  "Hide foreign contract activity": "隐藏外部合约活动",
  "Filter by direction and token": "按方向和代币筛选",
  "Copy the listed rows": "复制列出的行",
  "Search address, id, token, amount…": "搜索地址、ID、代币、金额…",
  "Search history": "搜索历史记录",
  "Copy output": "复制输出",
  "Clear": "清除",
  "Commands run against your live node immediately. There is no confirmation step.": "命令会立即在您正在运行的节点上执行。没有确认步骤。",
  "Enter command": "输入命令",
  "Node command": "节点命令",
  "Run": "运行",
  "Save to file": "保存到文件",
  "Filter": "筛选",
  "Filter the log": "筛选日志",
  "What the node logs": "节点记录的日志",
  "Hide takes an app out of the app drawer. Freeze also stops its background work until you turn it back on; nothing it holds is lost.": "“隐藏”会将应用从应用抽屉中移除。“冻结”还会停止其后台工作，直到您重新开启；它持有的任何内容都不会丢失。",
  "Log": "日志",
  "while the app is closed": "在应用关闭期间",
  "while the node is stopped": "在节点停止期间",
  "Open the app again": "重新打开应用",
  "Start the node again": "重新启动节点",
  "AtomiX swaps, market and OTC (AtomiX could not be asked)": "AtomiX 兑换、市场和 OTC（无法查询 AtomiX）",
  "AtomiX swaps, market and OTC (AtomiX has not started{why})": "AtomiX 兑换、市场和 OTC（AtomiX 尚未启动{why}）",
  "can time out": "可能超时",
  "can time out: the time limit of its lock has already passed and its refund is waiting to be made": "可能超时：其锁定的时限已过，退款正等待执行",
  "can time out: the time limit of the first lock has already passed and its refund is waiting to be made": "可能超时：第一笔锁定的时限已过，其退款正等待执行",
  "can time out at about {time}": "可能在 {time} 左右超时",
  "can time out at {time}": "可能在 {time} 超时",
  "(the first of them)": "（其中最早的一笔）",
  "{n} AtomiX swaps are not finished. A swap in progress cannot settle {off} and {when}. {back} well before then: if the other side completes its part in the meantime, this app must be running to claim yours.": { other: "{n} 笔 AtomiX 兑换尚未完成。进行中的兑换{off}无法结算，并且{when}。请务必在此之前尽早{back}：如果对方在此期间完成了其部分，此应用必须处于运行状态才能领取您的部分。" },
  "Your AtomiX market is on the book. Its orders stay there, but a swap someone starts against them is not answered {off}.": "您的 AtomiX 市场已在订单簿上。其订单会保留在那里，但{off}，他人针对这些订单发起的兑换不会得到响应。",
  "Your AtomiX OTC availability is live. A proposal sent to you is not answered {off}.": "您的 AtomiX OTC 可交易额度已上线。{off}，发给您的提议不会得到响应。",
  "{n} AtomiX OTC deals are open and cannot go on {off}.": { other: "{n} 笔 AtomiX OTC 交易尚未完结，{off}无法继续进行。" },
  "pool operations (PandaPools has not started)": "池操作（PandaPools 尚未启动）",
  "{n} pool transactions sent in the last hour are not confirmed yet. The app cannot check or finish them {off}.": { other: "过去一小时内发送的 {n} 笔池交易尚未确认。{off}，应用无法检查或完成它们。" },
  "Exchange trades waiting for an answer (Dexicon could not be asked)": "等待响应的交易所交易（无法查询 Dexicon）",
  "Exchange trades waiting for an answer (Dexicon has not started)": "等待响应的交易所交易（Dexicon 尚未启动）",
  "{n} Exchange trades are sent and not yet answered. While the app is closed they cannot be voided, so the other side could still complete them later at the price you signed. Wait a few minutes until Dexicon, Orders shows no trade waiting.": { other: "{n} 笔交易所交易已发送但尚未得到响应。在应用关闭期间它们无法作废，因此对方之后仍可能按您已签名的价格完成这些交易。请等待几分钟，直到 Dexicon 的“订单”页面显示没有等待中的交易。" },
  "{n} Exchange trades are sent and not yet answered. While the node is stopped they cannot be voided, so the other side could still complete them later at the price you signed. Wait a few minutes until Dexicon, Orders shows no trade waiting.": { other: "{n} 笔交易所交易已发送但尚未得到响应。在节点停止期间它们无法作废，因此对方之后仍可能按您已签名的价格完成这些交易。请等待几分钟，直到 Dexicon 的“订单”页面显示没有等待中的交易。" },
  "{n} fills of your Exchange orders have an outcome that is not known yet (the node did not answer when they were posted). The chain decides; the app can only read the answer while it runs.": { other: "您的交易所订单有 {n} 笔成交结果尚不明确（提交时节点没有响应）。结果由链决定；应用只有在运行时才能读取结果。" },
  "{n} Exchange orders are still waiting for a block.": { other: "{n} 笔交易所订单仍在等待区块。" },
  "P2P Chance: {bets} and {offers} still open. They are revealed and paid out only while the app and its node run; a bet that is not settled before its deadline can be claimed by the other side.": "P2P Chance：仍有 {bets} 和 {offers} 未完结。只有在应用及其节点运行时，它们才会被揭示并派付；未在截止时间前结算的投注可被对方领取。",
  "{n} bets": { other: "{n} 笔投注" },
  "{n} offers": { other: "{n} 个报价" },
  "P2P Chance bets (not read yet)": "P2P Chance 投注（尚未读取）",
  "Could not be checked: {what}. {advice}": "无法检查：{what}。{advice}",
  "If you are not sure nothing is in flight, stay open and look at the Dexicon tab first.": "如果您不确定是否没有任何进行中的事项，请保持应用开启，并先查看 Dexicon 标签页。",
  "Look at the Dexicon tab before you shut down.": "关闭节点前请先查看 Dexicon 标签页。",
  "The app closes and its node stops. Swaps, pools, orders, mail and chat stop being served until you open it again.": "应用将关闭，其节点将停止。在您重新打开应用之前，兑换、池、订单、邮件和聊天都将停止服务。",
  "The node stops and this wallet goes offline. Swaps, pools, mail and chat stop being served until you start it again.": "节点将停止，此钱包将离线。在您重新启动节点之前，兑换、池、邮件和聊天都将停止服务。",
  "Quit with work in flight?": "仍有事项进行中，确定退出？",
  "Shut down with trades in flight?": "仍有交易进行中，确定关闭节点？",
  "Quit without the check?": "不经检查就退出？",
  "Quit?": "退出？",
