    "⚠ You only have {avail} {name}.",
    "This app and its node must run regularly.\n\nYour pool's reserve coins have to be recreated about every 900 blocks, roughly twice a day. PandaPools does that by itself while the app and the node run. If it cannot, other wallets stop finding your pool, and after about 1700 blocks its coins drop out of the chain's recent window and can only be recovered through a MegaMMR archive.",
    "Save the backup and keep your wallet seed safe.\n\nRight after the pool is created you are asked to save one encrypted file with your pools and this node's backup. Until it is saved and checked, another pool cannot be created or migrated. Keep it off this device.",
    "I understand: I must keep this app running, save the backup and keep my wallet seed safe.",
    "No market price is available (MEXC is unreachable and there are no live MINIMA / {name} pools to match). You are setting the OPENING PRICE yourself: set it to the true market rate, or arbitrageurs will correct it at your expense.",
    "Use at least 12 characters and enter the same password twice. Nothing was saved.",
    "The file that was written is not the same as the backup that was made, so it does not count as saved. Save it again in another place.",
    "That file is too large to be a PandaPools backup. Nothing was read from it.",
    "The node backup that was written is not the same as the one in the file, so do not use it. Extract it again to another place.",
    "No reason was given.",
    "Save one file containing your pools and the native node backup, including wallet keys. Use at least 12 characters, ideally random words. Keep the password safe; there is no password reset. The saved file is checked before another pool can be created.",
    "Restore public pool recipes and verify reserves on this node. Expired proofs need a synced MegaMMR archive. Owner signing stays paused until you confirm current wallet signing state.",
    "Node backup saved. Restore this .bak through MinimaCore's node restore flow, using the password below. Then reopen the combined file to recover the pool recipes. An old backup still requires verification of current signing state.",
    "Optional public HTTPS MegaMMR RPC endpoint for current proofs. Your node verifies every proof. Leave empty for local MegaMMR or backup proofs.",
    "Keep the latest complete MinimaCore wallet backup and this pool recipe. Proofs expire. A seed or recipe alone is insufficient.\n\nSaved recipes identify pools even when a light node no longer sees their coins. Restore verifies local reserves, then backup proofs, then current proofs from a synced MegaMMR archive. Missing reserves remain visible and are never reported as recovered.\n\nRestore does not regenerate keys or estimate past signature use. Confirm signing only with current complete wallet state and no other signing copies. Keep-fresh requires the app and node to remain running; it cannot guarantee availability while offline.",
    "The backup dialog was closed while the backup was still being made, so it is not known yet whether it was saved. If a file was written and checked, the \"backup required\" notice in My LP goes away by itself. If the notice is still there in a minute, use Back up now.",
    "The backup was not saved. Your pool is not affected, but another pool cannot be created or migrated until the backup is saved: use Back up now.",
